#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Variables (w h : R). Let A : 'rV[R]_2 := row2 0 0. Let B : 'rV[R]_2 := row2 w 0. Let C : 'rV[R]_2 := row2 w h. Let D : 'rV[R]_2 := row2 0 h. Variable xE : R. Hypothesis AE_pos : 0 < xE. Hypothesis AE_val : xE = 8. Let E : 'rV[R]_2 := row2 xE 0. Variable xF : R. Hypothesis CF_pos : 0 < xF. Hypothesis CF_val : (w - xF) = 3. Let F : 'rV[R]_2 := row2 xF h. Hypothesis BE_val : `|w - xE| = 17. Variable B' : 'rV[R]_2. Hypothesis B'_on_AD : B' \in [seg A D]. Hypothesis reflect_B_to_B' : exists crease, reflect_point crease B = B' /\ crease \in line E F. Theorem fold_geometry_constraints : exists w h : R, w > 0 /\ h > 0 /\ w - xE = 17 /\ xF = w - 3 /\ xE = 8. Proof. Admitted.
